,2,3004581[3009002][3003124][3003651],1[2][50][1]"	--------------------------------------逻辑部分--------------------------------------------- 选择一个物品获得function DaylyTopCPsPack_RewardOne(nItemId,nIndex)	-- 检测物品是否存在	if not Item_ChkItem(nItemId) then		return false	end	RewardTemplate_UseItem(tDaylyTopCPsPack_Reward[nItemId][nIndex])end-- 4选2获得密令function DaylyTopCPsPack_RewardTwoToken(nItemId,nNum,nIndex)	-- 检测物品是否存在	if not Item_ChkItem(nItemId) then		return false	end		local nEvent = tDaylyTopCPsPack_Stc[nItemId]["EventType"]	local nType = tDaylyTopCPsPack_Stc[nItemId]["DataType"]	local nData = Get_UserStatisticValue(nEvent,nType)		if nNum == 1 and nData ~= 0 then		Task_SetStatistic(nEvent,nType,0,1) 		nData = 0	end		if nData == 0 then  -- 第一次选择		Task_SetStatistic(nEvent,nType,nIndex,1) 				local sTalk = tDaylyTopCPsPack_Text[nItemId]["211"]		local sName = tDaylyTopCPsPack_Text["TokenName"][nIndex]				tItem[nItemId]["Text211"]  = string.format(sTalk,sName)		LinkItemGossipFunc_New(nItemId,"2-1")	elseif nData == nIndex then  -- 两次选择相同		Task_SetStatistic(nEvent,nType,0,1)  -- 掩码先置零		RewardTemplate_UseItem(tDaylyTopCPsPack_Reward[nItemId][nData][nIndex])		return true	else  --两次选择不同		Task_SetStatistic(nEvent,nType,0,1)				local nSpace = RewardTemplate_GetRewardSpace(tDaylyTopCPsPack_Reward[nItemId][1][2]) - RewardTemplate_GetDelSpace(tDaylyTopCPsPack_Reward[nItemId][1][2])		-- 判断背包空间		if not User_CheckLeftSpace(nSpace) then			Sys_MsgBox(string.format(tDaylyTopCPsPack_Text["FullBag"],nSpace))			return false		end		if nData < nIndex then			RewardTemplate_UseItem(tDaylyTopCPsPack_Reward[nItemId][nData][nIndex])		else			RewardTemplate_UseItem(tDaylyTopCPsPack_Reward[nItemId][nIndex][nData])		end		return true	endend--------------------------------------物品配置-------------------------------------------tItem[3304035] = tItem[3304035] or {}tItem[3304036] = tItem[3304035] or {}tItem[3304037] = tItem[3304035] or {}tItem[3304038] 